//! Known-answer tests for the AES block cipher and the CBC/CTR modes of operation.
//!
//! Every vector here is quoted from a published standard, not generated by this implementation:
//!
//! * **FIPS 197 Appendix B and C** — the single-block ciphertexts for the 128-, 192- and
//!   256-bit keys, which are what "an AES implementation" means.
//! * **NIST SP 800-38A Appendix F.2** — the four-block CBC vectors for each key size, which
//!   catch a correct block cipher wired into chaining the wrong way round.
//! * **NIST SP 800-38A Appendix F.5** — the CTR vectors, which the GCM implementation depends
//!   on through `GCTR`.
//!
//! Decryption is checked against the same vectors in reverse, so a cipher that is
//! self-consistent but wrong cannot pass.

use oxixml_enc::EncError;
use oxixml_enc::crypto::aes::{Aes, BLOCK_SIZE};
use oxixml_enc::crypto::{cbc, ctr};
use oxixml_text::hex;

/// Decodes a hex string from a test vector.
fn unhex(text: &str) -> Vec<u8> {
    hex::decode(text).expect("the embedded test vectors are valid hex")
}

/// The four plaintext blocks NIST SP 800-38A uses throughout Appendix F.
const SP800_38A_PLAINTEXT: &str = concat!(
    "6bc1bee22e409f96e93d7e117393172a",
    "ae2d8a571e03ac9c9eb76fac45af8e51",
    "30c81c46a35ce411e5fbc1191a0a52ef",
    "f69f2445df4f9b17ad2b417be66c3710",
);

/// The AES-128 key of SP 800-38A.
const KEY_128: &str = "2b7e151628aed2a6abf7158809cf4f3c";
/// The AES-192 key of SP 800-38A.
const KEY_192: &str = "8e73b0f7da0e6452c810f32b809079e562f8ead2522c6b7b";
/// The AES-256 key of SP 800-38A.
const KEY_256: &str = "603deb1015ca71be2b73aef0857d77811f352c073b6108d72d9810a30914dff4";

#[test]
fn fips_197_appendix_c_known_answers() -> Result<(), EncError> {
    // FIPS 197 Appendix C.1, C.2 and C.3: key = 00 01 02 … , plaintext = 00 11 22 … ff.
    let plaintext = unhex("00112233445566778899aabbccddeeff");
    let cases = [
        (16usize, "69c4e0d86a7b0430d8cdb78070b4c55a"),
        (24, "dda97ca4864cdfe06eaf70a0ec0d7191"),
        (32, "8ea2b7ca516745bfeafc49904b496089"),
    ];

    for (key_len, expected) in cases {
        let key: Vec<u8> = (0..key_len as u8).collect();
        let aes = Aes::new(&key)?;

        let mut block = [0u8; BLOCK_SIZE];
        block.copy_from_slice(&plaintext);
        aes.encrypt_block(&mut block);
        assert_eq!(
            block.to_vec(),
            unhex(expected),
            "AES-{} encryption",
            key_len * 8
        );

        aes.decrypt_block(&mut block);
        assert_eq!(block.to_vec(), plaintext, "AES-{} decryption", key_len * 8);
    }
    Ok(())
}

#[test]
fn fips_197_appendix_b_worked_example() -> Result<(), EncError> {
    // The step-by-step example of FIPS 197 Appendix B.
    let aes = Aes::new(&unhex(KEY_128))?;
    let mut block = [0u8; BLOCK_SIZE];
    block.copy_from_slice(&unhex("3243f6a8885a308d313198a2e0370734"));
    aes.encrypt_block(&mut block);
    assert_eq!(block.to_vec(), unhex("3925841d02dc09fbdc118597196a0b32"));
    Ok(())
}

#[test]
fn sp_800_38a_cbc_known_answers() -> Result<(), EncError> {
    // SP 800-38A Appendix F.2.1/F.2.3/F.2.5, which all share this initialization vector.
    let iv_bytes = unhex("000102030405060708090a0b0c0d0e0f");
    let mut iv = [0u8; BLOCK_SIZE];
    iv.copy_from_slice(&iv_bytes);
    let plaintext = unhex(SP800_38A_PLAINTEXT);

    let cases = [
        (
            KEY_128,
            concat!(
                "7649abac8119b246cee98e9b12e9197d",
                "5086cb9b507219ee95db113a917678b2",
                "73bed6b8e3c1743b7116e69e22229516",
                "3ff1caa1681fac09120eca307586e1a7",
            ),
        ),
        (
            KEY_192,
            concat!(
                "4f021db243bc633d7178183a9fa071e8",
                "b4d9ada9ad7dedf4e5e738763f69145a",
                "571b242012fb7ae07fa9baac3df102e0",
                "08b0e27988598881d920a9e64f5615cd",
            ),
        ),
        (
            KEY_256,
            concat!(
                "f58c4c04d6e5f1ba779eabfb5f7bfbd6",
                "9cfc4e967edb808d679f777bc6702c7d",
                "39f23369a9d9bacfa530e26304231461",
                "b2eb05e2c39be9fcda6c19078c6a9d1b",
            ),
        ),
    ];

    for (key, expected) in cases {
        let aes = Aes::new(&unhex(key))?;
        let ciphertext = cbc::encrypt(&aes, &iv, &plaintext)?;
        assert_eq!(ciphertext, unhex(expected), "CBC encryption with key {key}");
        assert_eq!(
            cbc::decrypt(&aes, &iv, &ciphertext)?,
            plaintext,
            "CBC decryption with key {key}"
        );
    }
    Ok(())
}

#[test]
fn sp_800_38a_ctr_known_answers() -> Result<(), EncError> {
    // SP 800-38A Appendix F.5.1 and F.5.5.
    let counter_bytes = unhex("f0f1f2f3f4f5f6f7f8f9fafbfcfdfeff");
    let mut counter = [0u8; BLOCK_SIZE];
    counter.copy_from_slice(&counter_bytes);
    let plaintext = unhex(SP800_38A_PLAINTEXT);

    let cases = [
        (
            KEY_128,
            concat!(
                "874d6191b620e3261bef6864990db6ce",
                "9806f66b7970fdff8617187bb9fffdff",
                "5ae4df3edbd5d35e5b4f09020db03eab",
                "1e031dda2fbe03d1792170a0f3009cee",
            ),
        ),
        (
            KEY_256,
            concat!(
                "601ec313775789a5b7a7f504bbf3d228",
                "f443e3ca4d62b59aca84e990cacaf5c5",
                "2b0930daa23de94ce87017ba2d84988d",
                "dfc9c58db67aada613c2dd08457941a6",
            ),
        ),
    ];

    for (key, expected) in cases {
        let aes = Aes::new(&unhex(key))?;
        let mut data = plaintext.clone();
        ctr::apply(&aes, &counter, &mut data, ctr::increment_full);
        assert_eq!(data, unhex(expected), "CTR with key {key}");
        // Counter mode is an involution.
        ctr::apply(&aes, &counter, &mut data, ctr::increment_full);
        assert_eq!(data, plaintext);
    }
    Ok(())
}

#[test]
fn ctr_handles_a_partial_final_block() -> Result<(), EncError> {
    // SP 800-38A §6.5: the last block uses only as much keystream as it needs, so a truncated
    // message must be a prefix of the full one.
    let aes = Aes::new(&unhex(KEY_128))?;
    let counter_bytes = unhex("f0f1f2f3f4f5f6f7f8f9fafbfcfdfeff");
    let mut counter = [0u8; BLOCK_SIZE];
    counter.copy_from_slice(&counter_bytes);

    let plaintext = unhex(SP800_38A_PLAINTEXT);
    let mut full = plaintext.clone();
    ctr::apply(&aes, &counter, &mut full, ctr::increment_full);

    for length in [1usize, 7, 16, 17, 63] {
        let mut partial = plaintext[..length].to_vec();
        ctr::apply(&aes, &counter, &mut partial, ctr::increment_full);
        assert_eq!(partial, full[..length], "truncated to {length} octets");
    }
    Ok(())
}

#[test]
fn every_key_length_round_trips_over_random_looking_data() -> Result<(), EncError> {
    // A blunt consistency check across many blocks, to catch an error that only shows up in a
    // round the fixed vectors happen not to exercise.
    for key_len in [16usize, 24, 32] {
        let key: Vec<u8> = (0..key_len)
            .map(|index| (index as u8).wrapping_mul(37))
            .collect();
        let aes = Aes::new(&key)?;
        for seed in 0..64u8 {
            let mut block = [0u8; BLOCK_SIZE];
            for (index, byte) in block.iter_mut().enumerate() {
                *byte = seed.wrapping_mul(index as u8).wrapping_add(seed);
            }
            let original = block;
            aes.encrypt_block(&mut block);
            assert_ne!(block, original);
            aes.decrypt_block(&mut block);
            assert_eq!(block, original);
        }
    }
    Ok(())
}
